# Configuration for OpenAI Whisper API

To use this STT service in bot.py, replace the STT initialization with:

from pipecat.services.openai.stt import OpenAISTTService

stt = OpenAISTTService(
    api_key=os.getenv("API_KEY"),  # Use appropriate env var
    **{
    "model": "whisper-1"
}
)
